"""Per-connection TCP latency measurements: round-trip time, HTTP response time, TLS hello time.

Three different things are measured and kept apart (they must never be presented as one number):

* **TCP RTT** - a data segment sent by one side and the *pure ACK* (no payload, generated by the
  peer's TCP stack, not its application) that acknowledges exactly the end of that segment. Samples
  that cannot be trusted are discarded (Karn's rule): a retransmitted or reordered segment, and every
  segment after it that is only acknowledged cumulatively through it. Piggybacked ACKs on data are not
  sampled because they include the peer application's processing time. The handshake is timed
  separately (``connection_tracker.resolve_handshake``) and is not an RTT sample.
* **HTTP response time** - only for cleartext HTTP/1.x where a request line and a status line are both
  visible (``PacketRecord.app_hint``): last request packet -> first response packet. Pipelined or
  unanswered requests, and retransmitted request packets, are not timed.
* **TLS hello time** - ClientHello -> ServerHello of an encrypted connection. It is *not* a response
  time: HTTP inside TLS is not visible.

Nothing is estimated when the packets needed are missing; the corresponding result is simply absent.
"""
from __future__ import annotations

import math
import random
import statistics
from dataclasses import dataclass, field

from app.analysis.connection_tracker import FlowKey, flow_key
from app.analysis.pcap_parser import (
    HTTP_REQUEST, HTTP_RESPONSE, TLS_CLIENT_HELLO, TLS_SERVER_HELLO, PacketRecord,
)
from app.analysis.tcp_analyzer import ACK, FIN, RST, SYN

_MAX_FLOWS = 100_000
_MAX_PENDING_SEGMENTS = 64   # unacknowledged data segments remembered per direction
_MAX_SAMPLES_KEPT = 100      # RTT samples retained per direction for median/P95 (count/min/avg/max are exact)
_MAX_HTTP_SAMPLES = 32
_MAX_SEEN_SEQS = 16
MIN_SAMPLES_FOR_P95 = 5
_SEQ_MASK = 0xFFFFFFFF


def _after(a: int, b: int) -> bool:
    """TCP serial-number arithmetic: is sequence number ``a`` after ``b`` (mod 2**32)?"""
    return a != b and ((a - b) & _SEQ_MASK) < 0x80000000


def percentile(sorted_values: list[float], pct: float) -> float:
    """Nearest-rank percentile of an ascending list (``pct`` in 0..100)."""
    rank = max(1, math.ceil(pct / 100 * len(sorted_values)))
    return sorted_values[rank - 1]


@dataclass(slots=True)
class _Direction:
    """Data sent in one direction and acknowledged by the peer's pure ACKs."""

    pending: dict[int, list] = field(default_factory=dict)  # segment end seq -> [timestamp, ambiguous]
    max_end: int | None = None
    segments: int = 0
    ambiguous_segments: int = 0
    n: int = 0
    total: float = 0.0
    low: float = math.inf
    high: float = 0.0
    kept: list[float] = field(default_factory=list)


@dataclass(slots=True)
class _Http:
    client_dir: int | None = None
    pending_ts: float | None = None
    pipelined: bool = False
    seen_seqs: list[int] = field(default_factory=list)
    responses_ms: list[float] = field(default_factory=list)
    requests: int = 0
    untimed: int = 0  # requests/responses seen but not reliably pairable


@dataclass(slots=True)
class _Tls:
    hello_ts: float | None = None
    hello_seq: int | None = None
    hello_dir: int | None = None
    ambiguous: bool = False
    server_hello_ts: float | None = None


@dataclass(slots=True)
class _Flow:
    dirs: tuple[_Direction, _Direction] = field(default_factory=lambda: (_Direction(), _Direction()))
    http: _Http | None = None
    tls: _Tls | None = None


@dataclass(frozen=True, slots=True)
class RttStats:
    """RTT of one flow. ``direction`` 0/1 is the canonical endpoint order of the flow key (the side that sent the
    measured data); ``ambiguous_ratio`` is the share of that direction's segments excluded as retransmitted/reordered."""

    direction: int
    samples: int
    min_ms: float
    avg_ms: float
    median_ms: float
    p95_ms: float | None  # None below MIN_SAMPLES_FOR_P95 samples
    max_ms: float
    ambiguous_ratio: float
    retained: tuple[float, ...]  # up to _MAX_SAMPLES_KEPT samples, for pooling per domain


@dataclass(frozen=True, slots=True)
class FlowLatency:
    rtt: RttStats | None
    http_requests: int
    http_response_ms: tuple[float, ...]  # reliably paired request->response times
    http_untimed: int
    tls_seen: bool
    tls_hello_ms: float | None


class LatencyAnalyzer:
    """Feed every packet with ``add``; read per-flow results with ``flow`` (keyed by ``flow_key``)."""

    def __init__(self) -> None:
        self._flows: dict[FlowKey, _Flow] = {}
        self._dropped = 0
        self._rng = random.Random(0)  # reservoir sampling: deterministic output for a given capture

    # ------------------------------------------------------------------ intake
    def add(self, pkt: PacketRecord) -> None:
        if pkt.transport != "TCP" or pkt.tcp_flags is None or pkt.tcp_seq is None:
            return
        if not pkt.src_ip or not pkt.dst_ip:
            return
        flags = pkt.tcp_flags
        if flags & RST:
            return
        src, dst = (pkt.src_ip, pkt.src_port), (pkt.dst_ip, pkt.dst_port)
        key = flow_key("TCP", src, dst)
        flow = self._flows.get(key)
        if flow is None:
            is_data = bool(pkt.payload_len) and not flags & (SYN | FIN)
            is_pure_ack = bool(flags & ACK) and not pkt.payload_len and not flags & (SYN | FIN)
            if not (is_data or is_pure_ack):
                return  # nothing measurable yet; do not allocate state for handshake/teardown-only flows
            if len(self._flows) >= _MAX_FLOWS:
                self._dropped += 1
                return
            flow = self._flows[key] = _Flow()
        direction = 0 if src == key[1] else 1  # canonical: same side as flow_key's first endpoint

        if pkt.payload_len and not flags & (SYN | FIN):
            self._on_data(flow, direction, pkt)
        elif flags & ACK and not flags & (SYN | FIN) and pkt.tcp_ack is not None:
            self._on_pure_ack(flow, 1 - direction, pkt)

    def _on_data(self, flow: _Flow, direction: int, pkt: PacketRecord) -> None:
        assert pkt.tcp_seq is not None and pkt.payload_len
        d = flow.dirs[direction]
        seq, end, ts = pkt.tcp_seq, (pkt.tcp_seq + pkt.payload_len) & _SEQ_MASK, pkt.timestamp
        d.segments += 1
        if d.max_end is None or _after(end, d.max_end):
            if len(d.pending) >= _MAX_PENDING_SEGMENTS:
                d.pending.pop(next(iter(d.pending)))
            d.pending[end] = [ts, False]
            d.max_end = end
        else:
            # Retransmission or reordering: this segment, and everything sent after it that is only
            # acknowledged cumulatively through it, can no longer yield an unambiguous sample.
            d.ambiguous_segments += 1
            for pend_end, entry in d.pending.items():
                if _after(pend_end, seq):
                    entry[1] = True
        if pkt.tcp_ack is not None and pkt.tcp_flags is not None and pkt.tcp_flags & ACK:
            # A data packet's ACK acknowledges the peer's data too, but not as a sample (it includes
            # application think time); it only clears what is no longer outstanding.
            self._clear_acked(flow.dirs[1 - direction], pkt.tcp_ack)
        self._on_application(flow, direction, pkt)

    def _on_pure_ack(self, flow: _Flow, acked_direction: int, pkt: PacketRecord) -> None:
        d = flow.dirs[acked_direction]
        entry = d.pending.get(pkt.tcp_ack)  # type: ignore[arg-type]
        if entry is not None and not entry[1] and pkt.timestamp >= entry[0]:
            self._add_sample(d, (pkt.timestamp - entry[0]) * 1000)
        self._clear_acked(d, pkt.tcp_ack)  # type: ignore[arg-type]

    @staticmethod
    def _clear_acked(d: _Direction, ack: int) -> None:
        for pend_end in [e for e in d.pending if not _after(e, ack)]:
            del d.pending[pend_end]

    def _add_sample(self, d: _Direction, ms: float) -> None:
        d.n += 1
        d.total += ms
        d.low = min(d.low, ms)
        d.high = max(d.high, ms)
        if len(d.kept) < _MAX_SAMPLES_KEPT:
            d.kept.append(ms)
        else:  # reservoir sampling keeps a uniform sample of a long flow
            j = self._rng.randrange(d.n)
            if j < _MAX_SAMPLES_KEPT:
                d.kept[j] = ms

    # ------------------------------------------------------------------ HTTP / TLS (cleartext HTTP, TLS hellos)
    def _on_application(self, flow: _Flow, direction: int, pkt: PacketRecord) -> None:
        hint, ts, seq = pkt.app_hint, pkt.timestamp, pkt.tcp_seq
        assert seq is not None
        http = flow.http
        if hint == HTTP_REQUEST:
            http = flow.http = flow.http or _Http()
            if seq in http.seen_seqs:
                return  # retransmitted request packet: keep the original timestamp
            self._remember_seq(http, seq)
            http.requests += 1
            if http.pending_ts is not None:
                http.pipelined = True  # a second request before any response: pairs are no longer reliable
            http.client_dir = direction
            http.pending_ts = ts
        elif hint == HTTP_RESPONSE and http is not None and http.client_dir is not None and direction != http.client_dir:
            if http.pending_ts is None:
                return  # response without a visible request (or a retransmitted response)
            if http.pipelined or ts < http.pending_ts:
                http.untimed += 1
            elif len(http.responses_ms) < _MAX_HTTP_SAMPLES:
                http.responses_ms.append((ts - http.pending_ts) * 1000)
            http.pending_ts, http.pipelined = None, False
        elif http is not None and direction == http.client_dir and http.pending_ts is not None and seq not in http.seen_seqs:
            self._remember_seq(http, seq)  # request body continues: the request ends at its last packet
            http.pending_ts = max(http.pending_ts, ts)
        elif hint == TLS_CLIENT_HELLO:
            tls = flow.tls = flow.tls or _Tls()
            if tls.hello_ts is None:
                tls.hello_ts, tls.hello_seq, tls.hello_dir = ts, seq, direction
            else:
                tls.ambiguous = True  # retransmitted ClientHello or a second hello (HelloRetryRequest)
        elif hint == TLS_SERVER_HELLO:
            tls = flow.tls = flow.tls or _Tls()
            if tls.server_hello_ts is None and tls.hello_ts is not None and direction != tls.hello_dir:
                tls.server_hello_ts = ts

    @staticmethod
    def _remember_seq(http: _Http, seq: int) -> None:
        if len(http.seen_seqs) >= _MAX_SEEN_SEQS:
            http.seen_seqs.pop(0)
        http.seen_seqs.append(seq)

    # ------------------------------------------------------------------ results
    def flow(self, key: FlowKey) -> FlowLatency | None:
        flow = self._flows.get(key)
        if flow is None:
            return None
        http, tls = flow.http, flow.tls
        hello_ms = None
        if tls is not None and not tls.ambiguous and tls.hello_ts is not None and tls.server_hello_ts is not None \
                and tls.server_hello_ts >= tls.hello_ts:
            hello_ms = round((tls.server_hello_ts - tls.hello_ts) * 1000, 3)
        return FlowLatency(
            rtt=self._rtt(flow),
            http_requests=http.requests if http else 0,
            http_response_ms=tuple(round(v, 3) for v in http.responses_ms) if http else (),
            http_untimed=http.untimed if http else 0,
            tls_seen=tls is not None,
            tls_hello_ms=hello_ms,
        )

    @staticmethod
    def _rtt(flow: _Flow) -> RttStats | None:
        """RTT of the longer leg: data one side sent and the other acknowledged.

        At the capture point one leg is usually near zero (the local side) and the other spans the
        path to the far end, so the direction with the larger median is reported.
        """
        best: tuple[float, int, int] | None = None
        for i, d in enumerate(flow.dirs):
            if d.n:
                cand = (statistics.median(d.kept), d.n, i)
                if best is None or cand[:2] > best[:2]:
                    best = cand
        if best is None:
            return None
        median, _, i = best
        d = flow.dirs[i]
        ordered = sorted(d.kept)
        return RttStats(
            direction=i, samples=d.n, min_ms=round(d.low, 3), avg_ms=round(d.total / d.n, 3),
            median_ms=round(median, 3),
            p95_ms=round(percentile(ordered, 95), 3) if d.n >= MIN_SAMPLES_FOR_P95 else None,
            max_ms=round(d.high, 3),
            ambiguous_ratio=round(d.ambiguous_segments / d.segments, 4) if d.segments else 0.0,
            retained=tuple(d.kept),
        )

    @property
    def flows_not_tracked(self) -> int:
        return self._dropped
